/* ทดสอบ QR ที่เราเขียนเอง — รัน: node scripts/tests/qr.test.mjs
 *
 * 🔴 **ทำไมต้องมีเทส** — QR ที่วางบิตผิดจะ **ดูเหมือน QR ทุกประการ** แต่สแกนไม่ออก
 *    ดูด้วยตาไม่มีทางรู้ · เจอมาแล้วสองรอบระหว่างเขียน lib/qr.ts วันนี้:
 *      ① สลับแถว/คอลัมน์ของ format info (สำเนา ② ไปเขียนทับคอลัมน์ timing)
 *      ② เรียงบิต format info แบบ MSB ก่อน ทั้งที่กติกาอ้างถึงบิตแบบ LSB
 *    ทั้งสองรอบ tsc ผ่านสบาย และภาพที่ออกมา "เหมือน QR"
 *    (ตระกูลเดียวกับ lib/barcode128.ts — ฉลากที่พิมพ์ออกไปแล้วรู้ตอนหน้าเคาน์เตอร์)
 *
 * 🔑 **ของเทียบคือ `qrencode` ตัวมาตรฐาน** (ยิงจริง 14 ก.ย. 2569 ด้วย `-8 -l M -m 0 -t ASCII`)
 *    เก็บผลเป็น golden vector ไว้ในไฟล์นี้ ⇒ รันได้ทุกเครื่องแม้ไม่มี qrencode ติดตั้ง
 *    ⚠️ ถ้าจะเพิ่มเคส ให้สร้าง golden ด้วย qrencode เท่านั้น **ห้ามเอาผลของ lib/qr.ts มาเป็น golden**
 *       (เทสที่สร้างจากความเข้าใจผิดเดียวกับโค้ด จะเขียวเสมอ — บทเรียนสูตรเงินใบขาย)
 *
 * 🔵 **หน้ากาก (mask) เป็นเรื่องคุณภาพ ไม่ใช่ความถูกต้อง** — เลขหน้ากากเขียนอยู่ใน format info
 *    เครื่องสแกนจึงถอดได้ทุกหน้ากาก ⇒ เทสนี้แยกสองชั้น:
 *      ① บังคับหน้ากากให้ตรงกับ qrencode แล้วเทียบ **ทุกช่อง** (ตรวจความถูกต้องเต็มรูป)
 *      ② โหมดเลือกหน้ากากเอง: ถอดหน้ากากออกทั้งสองฝั่งแล้วเทียบ **เนื้อข้อมูล**
 *         ⇒ พิสูจน์ว่าเลือกหน้ากากต่างกันก็ยังเป็นข้อมูลชุดเดียวกัน
 */
import { execFileSync } from 'node:child_process'
import { mkdirSync, rmSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const GOLDEN = [
  { text: "03409-3", mask: 3, size: 21, bits: '' },
  { text: "00073-11.8-NW", mask: 2, size: 21, bits: '' },
  { text: "NW-01", mask: 3, size: 21, bits: '' },
  { text: "A", mask: 4, size: 21, bits: '' },
  { text: "0123456789", mask: 0, size: 21, bits: '' },
  { text: "01209-22.5T", mask: 6, size: 21, bits: '' },
  { text: "SET-NEWWAVE-9800-SUPER-PRO-24", mask: 1, size: 29, bits: '' },
  { text: "gucut", mask: 4, size: 21, bits: '' },
  { text: "โซ่17", mask: 6, size: 21, bits: '' },
]

const out = join(process.cwd(), 'scripts', 'tests', '.out-qr')
rmSync(out, { recursive: true, force: true })
mkdirSync(out, { recursive: true })
let fail = 0
try {
  execFileSync('npx', ['tsc', 'lib/qr.ts', '--outDir', out,
    '--target', 'es2020', '--module', 'esnext', '--moduleResolution', 'bundler',
    '--lib', 'es2020,dom', '--esModuleInterop', '--skipLibCheck'],
    { cwd: process.cwd(), stdio: 'inherit' })
  writeFileSync(join(out, 'package.json'), '{"type":"module"}')
  const { qrEncode } = await import(join(out, 'qr.js'))

  const ok = (name, cond, extra = '') => {
    if (cond) console.log(`  ✅ ${name}`)
    else { fail++; console.log(`  ❌ ${name} ${extra}`) }
  }
  const gridOf = (g) => {
    const m = []
    for (let r = 0; r < g.size; r++) {
      const row = []
      for (let c = 0; c < g.size; c++) row.push(Number(g.bits[r * g.size + c]))
      m.push(row)
    }
    return m
  }
  /* ตำแหน่งที่เป็น "ลายประจำ" (finder/timing/alignment/format/dark) — ไม่ใช่เนื้อข้อมูล */
  const isFunction = (size, r, c) => {
    const near = (r0, c0) => r >= r0 - 1 && r <= r0 + 7 && c >= c0 - 1 && c <= c0 + 7
    if (near(0, 0) || near(0, size - 7) || near(size - 7, 0)) return true
    if (r === 6 || c === 6) return true
    if (r === 8 || c === 8) return true
    const a = size === 21 ? null : (size - 17) / 4 * 4 + 10
    if (a !== null && Math.abs(r - a) <= 2 && Math.abs(c - a) <= 2) return true
    return false
  }
  const MASKS = [
    (r, c) => (r + c) % 2 === 0,
    (r) => r % 2 === 0,
    (_r, c) => c % 3 === 0,
    (r, c) => (r + c) % 3 === 0,
    (r, c) => (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0,
    (r, c) => ((r * c) % 2) + ((r * c) % 3) === 0,
    (r, c) => (((r * c) % 2) + ((r * c) % 3)) % 2 === 0,
    (r, c) => (((r + c) % 2) + ((r * c) % 3)) % 2 === 0,
  ]
  /** อ่านเลขหน้ากากออกจาก format info สำเนา ① (บิตแบบ LSB) */
  const maskOf = (m) => {
    const bits = []
    for (let i = 0; i <= 5; i++) bits[i] = m[i][8]
    bits[6] = m[7][8]; bits[7] = m[8][8]; bits[8] = m[8][7]
    for (let i = 9; i <= 14; i++) bits[i] = m[8][14 - i]
    let full = 0
    for (let i = 0; i < 15; i++) full |= bits[i] << i
    return ((full ^ 0b101010000010010) >> 10) & 7
  }
  /** ถอดหน้ากากออก แล้วคืนเฉพาะช่องเนื้อข้อมูลเป็นสตริง */
  const dataOf = (m) => {
    const size = m.length
    const mask = maskOf(m)
    let s = ''
    for (let r = 0; r < size; r++) for (let c = 0; c < size; c++) {
      if (isFunction(size, r, c)) continue
      s += String(m[r][c] ^ (MASKS[mask](r, c) ? 1 : 0))
    }
    return s
  }

  console.log('① 🔴 บังคับหน้ากากให้ตรงกับ qrencode ⇒ ต้องตรงทุกช่อง')
  for (const g of GOLDEN) {
    const want = gridOf(g)
    const got = qrEncode(g.text, g.mask)
    if (!got) { fail++; console.log(`  ❌ ${g.text} — คืน null`); continue }
    if (got.size !== g.size) { fail++; console.log(`  ❌ ${g.text} — ขนาด ${got.size} ควรเป็น ${g.size}`); continue }
    let bad = 0
    for (let r = 0; r < g.size; r++) for (let c = 0; c < g.size; c++) if (got.modules[r][c] !== want[r][c]) bad++
    ok(`${g.text} (${g.size}×${g.size} · หน้ากาก ${g.mask})`, bad === 0, `ต่าง ${bad} ช่อง`)
  }

  console.log('② เลือกหน้ากากเอง ⇒ เนื้อข้อมูลต้องเหมือนเดิมทุกบิต')
  for (const g of GOLDEN) {
    const auto = qrEncode(g.text)
    ok(`${g.text} — เนื้อข้อมูลตรงกับ qrencode (หน้ากาก ${auto ? maskOf(auto.modules) : '?'})`,
      auto !== null && auto.size === g.size && dataOf(auto.modules) === dataOf(gridOf(g)))
  }

  console.log('③ 🔴 ยาวเกินขอบเขตที่ตั้งใจ ⇒ ต้องคืน null ไม่ใช่วาดผิด ๆ')
  {
    ok('62 ไบต์ (เต็ม version 4) ยังทำได้', qrEncode('x'.repeat(62)) !== null)
    ok('🔴 63 ไบต์ ⇒ null (จอต้องเขียนว่าทำ QR ไม่ได้)', qrEncode('x'.repeat(63)) === null)
    ok('ไทยกินหลายไบต์ต่อตัว — 21 ตัว (63 ไบต์) ⇒ null', qrEncode('โ'.repeat(21)) === null)
    ok('ค่าว่าง ⇒ ยังทำได้ (ไม่ใช่ crash)', qrEncode('') !== null)
  }

  console.log('④ ลายประจำที่ขาดไม่ได้')
  for (const g of [GOLDEN[0], GOLDEN[6]]) {
    const m = qrEncode(g.text).modules
    const size = m.length
    ok(`${g.text} — finder สามมุมครบ`,
      m[0][0] === 1 && m[0][size - 1] === 1 && m[size - 1][0] === 1
      && m[3][3] === 1 && m[3][size - 4] === 1 && m[size - 4][3] === 1)
    ok(`${g.text} — ช่องดำบังคับที่ (${size - 8},8)`, m[size - 8][8] === 1)
    let timing = true
    for (let i = 8; i < size - 8; i++) if (m[6][i] !== (i % 2 === 0 ? 1 : 0)) timing = false
    ok(`${g.text} — แถบ timing ถูก`, timing)
  }
} finally {
  rmSync(out, { recursive: true, force: true })
}

console.log(fail ? `\n❌ ไม่ผ่าน ${fail} ข้อ` : '\n✅ ผ่านทุกข้อ')
process.exit(fail ? 1 : 0)
